    <select name="type"><?php foreach (Svc::PARTY_TYPES as $t): ?><option value="<?= e($t) ?>" <?= $s['type'] === $t ? 'selected' : '' ?>><?= e($sf->t('pt_' . $t)) ?></option><?php endforeach; ?></select><input name="position" value="<?= (int)$s['position'] ?>" inputmode="numeric" size="4" title="<?= e($sf->t('position')) ?>">
    <button class="btn sm primary"><?= e($sf->t('save')) ?></button><button class="btn sm danger" name="delete" value="1" formnovalidate data-x><?= e($sf->t('delete')) ?></button></form>
